p='src/server/services/usage-service.ts'
s=open(p).read()
old='''import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";'''
new='''import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { isBillableRole } from "@/types/member";
import type { MemberId, OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor, Role } from "@/types/member";'''
assert old in s
s=s.replace(old,new)
old='''/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate.
 */'''
new='''/** 1 when a member in `role` occupies a seat, 0 when they are free. */
function seatsFor(role: Role): number {
  return isBillableRole(role) ? 1 : 0;
}

/**
 * Whether the member's row is one the full recount counts (active, not
 * archived). An unknown member is assumed to be counted.
 */
async function isCountedMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<boolean> {
  const member = await memberRepo.findMemberById(orgId, memberId);
  if (!member) return true;
  return member.status === "active" && member.archivedAt === null;
}

/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate. Seat
 * deltas follow `recomputeUsage`: only billable roles occupy a seat.
 */'''
assert old in s
s=s.replace(old,new)
old='''    subscribe("member.joined", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
    }),
    subscribe("member.removed", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),'''
new='''    subscribe("member.joined", async (payload) => {
      const seatsUsed = seatsFor(payload.role);
      if (seatsUsed === 0) return;
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed });
    }),
    subscribe("member.role_changed", async (payload) => {
      const seatsUsed = seatsFor(payload.to) - seatsFor(payload.from);
      if (seatsUsed === 0) return;
      if (!(await isCountedMember(payload.orgId, payload.memberId))) return;
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed });
    }),
    subscribe("member.removed", async (payload) => {
      // The payload carries no role, but removal is a soft delete: the
      // archived row still says which role just left.
      const member = await memberRepo.findMemberById(
        payload.orgId,
        payload.memberId,
      );
      if (member && !isBillableRole(member.role)) return;
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
EOF

