s=s[:-3]+'''
  // Only owner, admin and member occupy a seat; a viewer is free.
  it("treats every role but viewer as billable", () => {
    expect(isBillableRole("owner")).toBe(true);
    expect(isBillableRole("admin")).toBe(true);
    expect(isBillableRole("member")).toBe(true);
    expect(isBillableRole("viewer")).toBe(false);
  });

  // Promoting a viewer takes a seat, so a full plan refuses it.
  it("refuses to promote a viewer when the plan's seats are taken", async () => {
    // Free plan: 3 seats, held by the fixture's owner, admin and member.
    const tenant = await createTenant("member-promote-full", "free");
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture member missing");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "member",
      }),
    ).rejects.toThrow(/seats/);

    await expect(
      memberRepo.findMemberById(tenant.org.id, viewer.id),
    ).resolves.toMatchObject({ role: "viewer" });
  });

  // Moves between billable roles and down to viewer never need a seat.
  it("never refuses a change between billable roles or to viewer on seats", async () => {
    const tenant = await createTenant("member-shuffle-full", "free");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!admin || !member || !viewer) throw new Error("fixture member missing");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: admin.id,
        role: "member",
      }),
    ).resolves.toMatchObject({ role: "member" });

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
        role: "viewer",
      }),
    ).resolves.toMatchObject({ role: "viewer" });

    // Demoting the member freed a seat, so the viewer can now take it.
    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "member",
      }),
    ).resolves.toMatchObject({ role: "member" });
  });

  // Seats in use are counted as for invitations: pending billable invites hold one.
  it("counts pending billable invitations when promoting a viewer", async () => {
    const tenant = await createTenant("member-promote-pending", "free");
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!member || !viewer) throw new Error("fixture member missing");

    // Free one seat, then hand it to a pending invitation.
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
      role: "viewer",
    });
    await invitationService.inviteMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      email: "pending@member-promote-pending.test",
      role: "member",
    });
    // A pending viewer invitation holds no seat.
    await invitationService.inviteMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      email: "watcher@member-promote-pending.test",
      role: "viewer",
    });

    await expect(invitationService.countSeatsInUse(tenant.org.id)).resolves.toBe(3);

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "admin",
      }),
    ).rejects.toThrow(/seats/);
  });

  // The incremental seat adjustments always agree with a full recount.
  it("keeps the seat counter in step with a recount as members come and go", async () => {
    const tenant = await createTenant("member-usage-deltas", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);
    const off = registerUsageListeners();

    async function expectCounterMatchesRecount(expected: number): Promise<void> {
      const cached = await usageRepo.getUsage(tenant.org.id);
      expect(cached.seatsUsed).toBe(expected);
      const recount = await usageRepo.recomputeUsage(tenant.org.id);
      expect(recount.seatsUsed).toBe(expected);
    }

    async function join(email: string, role: "member" | "viewer") {
      const token = `${role}-${email}`.padEnd(32, "x");
      await invitationRepo.insertInvitation(
        tenant.org.id,
        { orgId: tenant.org.id, email, role, expiresInDays: 14 },
        tenant.userIds.owner,
        hashToken(token),
      );
      const user = await userRepo.insertUser({ email, name: email, passwordHash: "seed" });
      return invitationService.acceptInvitation(user.id, { token });
    }

    try {
      await expectCounterMatchesRecount(3);

      const watcher = await join("watcher@member-usage-deltas.test", "viewer");
      await expectCounterMatchesRecount(3);

      const worker = await join("worker@member-usage-deltas.test", "member");
      await expectCounterMatchesRecount(4);

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: watcher.id,
        role: "admin",
      });
      await expectCounterMatchesRecount(5);

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: watcher.id,
        role: "member",
      });
      await expectCounterMatchesRecount(5);

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: worker.id,
        role: "viewer",
      });
      await expectCounterMatchesRecount(4);

      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: worker.id,
      });
      await expectCounterMatchesRecount(4);

      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: watcher.id,
      });
      await expectCounterMatchesRecount(3);
    } finally {
      off();
    }
  });
});
